pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    // Simple ERC20-like token for balance tracking
    address token;

    // We'll deploy a minimal ERC20 that C's transfer can call
    // Since the test only needs to observe token transfers, we'll use a mock

    function setUp() public {
        c = new C();
        token = address(new SimpleERC20());
        // Give the test contract some tokens to distribute
        // We'll deal tokens to 'from' addresses
    }

    function testFuzz_property(address from, address to, address[] memory _tos, uint256 v) public {
        // Ensure arrays are non-empty
        vm.assume(_tos.length > 0 && _tos.length <= 10);
        // Ensure from is not zero to avoid issues
        vm.assume(from != address(0));
        // Bound v to reasonable amount
        v = bound(v, 1, 1e18);

        // Deploy a simple ERC20 token and fund 'from'
        SimpleERC20 tok = new SimpleERC20();
        tok.mint(from, v * _tos.length);

        // Record balances before transfer
        uint256[] memory balancesBefore = new uint256[](_tos.length);
        for(uint i = 0; i < _tos.length; i++) {
            balancesBefore[i] = tok.balanceOf(_tos[i]);
        }

        // Ensure from has approved C to spend tokens (the C contract will call transferFrom)
        // We need to impersonate from to approve
        vm.prank(from);
        tok.approve(address(c), v * _tos.length);

        // Call transfer on C with the token address
        vm.prank(from);
        bool success = c.transfer(from, address(tok), _tos, v);
        require(success == true, "C transfer reverted");

        // Check each recipient: the reference should have transferred v to each
        for(uint i = 0; i < _tos.length; i++) {
            // After call, each recipient's balance should have increased by exactly v
            uint256 balanceDelta = tok.balanceOf(_tos[i]) - balancesBefore[i];
            // Every recipient must receive v exactly
            assertTrue(balanceDelta == v, "Recipient did not receive v");
        }
    }
}

// Minimal ERC20 for testing
contract SimpleERC20 {
    mapping(address => uint256) private _balances;
    mapping(address => mapping(address => uint256)) private _allowances;

    function mint(address to, uint256 amount) external {
        _balances[to] += amount;
    }

    function approve(address spender, uint256 amount) external returns (bool) {
        _allowances[msg.sender][spender] = amount;
        return true;
    }

    function transferFrom(address sender, address recipient, uint256 amount) external returns (bool) {
        require(_allowances[sender][msg.sender] >= amount, "allowance too low");
        require(_balances[sender] >= amount, "balance too low");
        _balances[sender] -= amount;
        _balances[recipient] += amount;
        _allowances[sender][msg.sender] -= amount;
        return true;
    }

    function balanceOf(address account) external view returns (uint256) {
        return _balances[account];
    }
}

