pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address caddress, address[] memory _tos, uint256 v) public {
        vm.assume(_tos.length > 0);
        vm.assume(_tos.length <= 100); // bound for gas
        // Record balances before
        uint256[] memory before = new uint256[](_tos.length);
        for (uint i = 0; i < _tos.length; i++) {
            (bool success, bytes memory data) = caddress.staticcall(abi.encodeWithSignature("balanceOf(address)", _tos[i]));
            require(success);
            before[i] = abi.decode(data, (uint256));
        }
        // Call transfer
        c.transfer(from, caddress, _tos, v);
        // Count recipients that received tokens (balance increased by v)
        uint256 countRecipients = 0;
        for (uint i = 0; i < _tos.length; i++) {
            (bool success, bytes memory data) = caddress.staticcall(abi.encodeWithSignature("balanceOf(address)", _tos[i]));
            require(success);
            uint256 after = abi.decode(data, (uint256));
            if (after == before[i] + v) {
                countRecipients++;
            }
        }
        // The rule: every recipient must receive tokens
        assertTrue(countRecipients == _tos.length);
    }
}

